// The difficulty picker (Easy · Normal · Hard), on the start screen and in "How it works". The
// choice is saved in the browser; each game keeps the mode it was started in. The sounds are the
// same in every mode: only what counts as a right answer changes. On the start screen the same
// panel also says where the animals come from (components/areapick.js).
import { store } from "../store.js";
import { sfx } from "../sfx.js";
import { areaButton } from "./areapick.js";

const MODES = [
  ["easy", "Easy", "Everyday names count: “toad”, “cricket”."],
  ["normal", "Normal", "Lookalike species get a little help."],
  ["hard", "Hard", "Exact species only. Every guess costs a try."],
];
const note = (mode) => MODES.find(([m]) => m === mode)[2];

/** area: put the part-of-the-world row on top (the start screen's panel). */
export function modePicker({ area = false } = {}) {
  const on = store.mode;
  return `<div class="mode-pick" data-mode-pick>${area ? areaButton("in-panel") : ""}
    <div class="mp-seg" role="radiogroup" aria-label="Difficulty">${MODES.map(
      ([m, label]) => `<button type="button" role="radio" data-mode="${m}" aria-checked="${m === on}" tabindex="${m === on ? 0 : -1}">${label}</button>`,
    ).join("")}</div>
    <small class="mp-note" aria-live="polite">${note(on)}</small>
  </div>`;
}

function choose(mode, focus = false) {
  if (mode === store.mode) return;
  sfx.tap();
  store.mode = mode;
  // Every picker on the page (start screen and "How it works") shows the same choice.
  document.querySelectorAll("[data-mode-pick]").forEach((el) => {
    el.querySelectorAll("[data-mode]").forEach((b) => {
      const on = b.dataset.mode === mode;
      b.setAttribute("aria-checked", String(on));
      b.tabIndex = on ? 0 : -1;
    });
    el.querySelector(".mp-note").textContent = note(mode);
  });
  if (focus) document.activeElement?.closest("[data-mode-pick]")?.querySelector(`[data-mode="${mode}"]`)?.focus();
}

document.addEventListener("click", (e) => {
  const b = e.target.closest("[data-mode-pick] [data-mode]");
  if (b) choose(b.dataset.mode);
});
// Arrow keys move the choice, like any radio group.
document.addEventListener("keydown", (e) => {
  const b = e.target.closest?.("[data-mode-pick] [data-mode]");
  if (!b || !["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown", "Home", "End"].includes(e.key)) return;
  e.preventDefault();
  const i = MODES.findIndex(([m]) => m === b.dataset.mode);
  const next = e.key === "Home" ? 0 : e.key === "End" ? MODES.length - 1 : (i + (e.key === "ArrowLeft" || e.key === "ArrowUp" ? -1 : 1) + MODES.length) % MODES.length;
  choose(MODES[next][0], true);
});
