// The part-of-the-world control: a row that says where the animals come from ("Animals from Europe"),
// on the start screen, in "How it works" and on Past days. Tapping it opens the map to pick another
// part (views/areas.js, fetched when first needed). The choice is saved in the browser, and every
// part keeps its own game for each day.
import { store } from "../store.js";
import { areaOf } from "../areas.js";
import { icon } from "../icons.js";
import { sfx } from "../sfx.js";
import { toast } from "../util.js";

export const loadAreaPicker = () => import("../views/areas.js");

export function areaButton(cls = "") {
  const a = areaOf(store.area);
  return `<button type="button" class="area-btn ${cls}" data-area-open aria-haspopup="dialog">${icon("globe")}<span class="ab-text">Animals from <b>${a.from}</b></span>${icon("chevron", "ab-more")}<span class="sr-only">. Choose a part of the world</span></button>`;
}

document.addEventListener("click", (e) => {
  if (!e.target.closest("[data-area-open]")) return;
  sfx.tap();
  loadAreaPicker()
    .then((m) => m.showAreaPicker())
    .catch(() => toast("Couldn't load the map. Check your connection and try again."));
});
