// Parts of the world. Each one has its own animal every day, picked from the animals that live there
// (tools/build-schedule.mjs), so friends who choose Europe all hear the same European animal. Pets
// and farm animals ("Worldwide" in answers.js) live everywhere, so they can turn up in every part; the
// open-ocean whales ("Oceans") only in the whole world. The choice is saved in the browser (store.area)
// and picked on the map in views/areas.js.
import { ANSWERS, DEMO_ID } from "./data/answers.js";

// name: in lists · from: after "Animals from" · short: the badge while you play
export const AREAS = [
  { key: "world", name: "Whole world", from: "the whole world", short: "World", continents: null, blurb: "Every animal in the game" },
  { key: "europe", name: "Europe", from: "Europe", short: "Europe", continents: ["Europe"], blurb: "Robins, cuckoos, hedgehogs, natterjack toads" },
  { key: "asia", name: "Asia", from: "Asia", short: "Asia", continents: ["Asia"], blurb: "Tigers, gibbons, peafowl, geckos" },
  { key: "africa", name: "Africa", from: "Africa", short: "Africa", continents: ["Africa"], blurb: "Lions, hyenas, lemurs, guineafowl" },
  { key: "americas", name: "The Americas", from: "the Americas", short: "Americas", continents: ["North America", "South America"], blurb: "Coyotes, loons, cardinals, spring peepers" },
  { key: "oceania", name: "Oceania", from: "Oceania", short: "Oceania", continents: ["Oceania"], blurb: "Kookaburras, kiwis, galahs, little penguins" },
];

export const AREA_KEYS = AREAS.map((a) => a.key);
export const areaOf = (key) => AREAS.find((a) => a.key === key) || AREAS[0];

/** Whether an answer can be an area's animal of the day. */
export function livesIn(answer, area) {
  const { continents } = typeof area === "string" ? areaOf(area) : area;
  return !continents || answer.continents.includes("Worldwide") || answer.continents.some((c) => continents.includes(c));
}

/** How many animals an area's days are drawn from. */
export const areaSize = (key) => Object.entries(ANSWERS).filter(([id, a]) => id !== DEMO_ID && livesIn(a, key)).length;
